const glob = require('glob');
const path = require('path');
const fs = require('fs');

const SENSITIVE_PATTERNS = [
  // Configuration files
  '**/config/**/*.{js,json,yaml,yml,xml,properties,conf,config}',
  '**/*.config.{js,json,yaml,yml,xml}',
  '**/configuration.{js,json,yaml,yml,xml}',
  '**/settings.{js,json,yaml,yml,xml}',

  // Environment files
  '**/.env*',
  '**/.env*.*',
  '**/env.{js,json,yaml,yml}',
  '**/environment.{js,json,yaml,yml}',

  // Key files
  '**/*.pem',
  '**/*.key',
  '**/*.cer',
  '**/*.crt',
  '**/*.pfx',
  '**/id_rsa*',
  '**/id_dsa*',
  '**/ssh_host_*_key*',
  '**/known_hosts',
  '**/authorized_keys*',
  '**/secret',
  '**/secrets.*',
  '**/private.*',
  '**/api-key*',
  '**/api_key*',
  '**/access_token*',
  '**/credentials*',
  '**/password*',
  '**/*.pgpass',
  '**/.netrc',
  '**/_netrc',
  '**/aws/credentials',
  '**/aws/config',
  '**/gcp/credentials.json',
  '**/kubeconfig',
  '**/.kube/config'
];

async function scanFiles(rootDir) {
  const results = [];

  for (const pattern of SENSITIVE_PATTERNS) {
    const files = await new Promise((resolve, reject) => {
      glob(path.join(rootDir, pattern), {
        ignore: [
          '**/node_modules/**',
          '**/bower_components/**',
          '**/vendor/**',
          '**/dist/**',
          '**/build/**',
          '**/.git/**',
          '**/.svn/**',
          '**/.hg/**'
        ],
        nodir: true,
        dot: true
      }, (err, matches) => {
        if (err) reject(err);
        else resolve(matches);
      });
    });

    for (const file of files) {
      try {
        const stat = await fs.promises.stat(file);
        const relativePath = path.relative(rootDir, file);

        results.push({
          path: relativePath,
          fullPath: file,
          size: stat.size,
          modified: stat.mtime,
          type: getFileType(relativePath)
        });
      } catch (err) {
        console.warn(`Could not access file ${file}:`, err.message);
      }
    }
  }

  return results;
}

function getFileType(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  const base = path.basename(filePath).toLowerCase();

  if (base.startsWith('.env')) return 'environment';
  if (ext === '.pem' || ext === '.key' || ext === '.cer' || ext === '.crt' || ext === '.pfx') return 'key';
  if (base.includes('config') || base.includes('setting') || base.includes('configuration')) return 'config';
  if (base.includes('secret') || base.includes('password') || base.includes('credential')) return 'secret';

  return 'other';
}

module.exports = { scanFiles };
