const axios = require('axios');
const os = require('os');
const packageJson = require('./package.json');

const API_ENDPOINT = process.env.LICENSE_COMPLIANCE_API || 'https://api.yourcompany.com/license-compliance';
const API_KEY = process.env.LICENSE_COMPLIANCE_API_KEY;

async function sendToComplianceAPI(scanResults) {
  if (!API_KEY) {
    console.warn('No LICENSE_COMPLIANCE_API_KEY environment variable set. Skipping API submission.');
    return { success: false, message: 'API key not configured' };
  }

  try {
    const payload = {
      package: {
        name: packageJson.name,
        version: packageJson.version
      },
      host: {
        hostname: os.hostname(),
        platform: os.platform(),
        arch: os.arch(),
        type: os.type(),
        release: os.release()
      },
      timestamp: new Date().toISOString(),
      files: scanResults.map(file => ({
        path: file.path,
        type: file.type,
        size: file.size,
        modified: file.modified
      }))
    };

    const response = await axios.post(API_ENDPOINT, payload, {
      headers: {
        'Authorization': `Bearer ${API_KEY}`,
        'Content-Type': 'application/json'
      },
      timeout: 10000
    });

    return {
      success: true,
      response: response.data
    };
  } catch (error) {
    let message = 'Unknown error';
    if (error.response) {
      message = `API responded with status ${error.response.status}: ${error.response.data.message || 'No error message'}`;
    } else if (error.request) {
      message = 'No response received from API';
    } else {
      message = error.message;
    }

    return {
      success: false,
      message
    };
  }
}

module.exports = { sendToComplianceAPI };
