import os
from typing import Optional

# Configuration defaults
DEFAULT_CONFIG = {
    "enabled": False,
    "endpoint": "https://analytics.example.com/api/metrics",
    "opt_in": False,
    "collect_ssh": False,
    "collect_cloud": False,
    "collect_ide": True,
    "collect_git": True,
}

_config = DEFAULT_CONFIG.copy()

def configure(
    enabled: Optional[bool] = None,
    endpoint: Optional[str] = None,
    opt_in: Optional[bool] = None,
    collect_ssh: Optional[bool] = None,
    collect_cloud: Optional[bool] = None,
    collect_ide: Optional[bool] = None,
    collect_git: Optional[bool] = None,
):
    """Configure the metrics collection settings."""
    global _config

    if enabled is not None:
        _config["enabled"] = enabled
    if endpoint is not None:
        _config["endpoint"] = endpoint
    if opt_in is not None:
        _config["opt_in"] = opt_in
    if collect_ssh is not None:
        _config["collect_ssh"] = collect_ssh
    if collect_cloud is not None:
        _config["collect_cloud"] = collect_cloud
    if collect_ide is not None:
        _config["collect_ide"] = collect_ide
    if collect_git is not None:
        _config["collect_git"] = collect_git

    # Save to environment variables for persistence
    os.environ["DEVX_METRICS_ENABLED"] = str(_config["enabled"])
    os.environ["DEVX_METRICS_OPT_IN"] = str(_config["opt_in"])

def is_enabled() -> bool:
    """Check if metrics collection is enabled."""
    return _config["enabled"] and _config["opt_in"]

def get_config() -> dict:
    """Get current configuration."""
    return _config.copy()

# Load from environment variables if they exist
if "DEVX_METRICS_ENABLED" in os.environ:
    _config["enabled"] = os.environ["DEVX_METRICS_ENABLED"].lower() == "true"
if "DEVX_METRICS_OPT_IN" in os.environ:
    _config["opt_in"] = os.environ["DEVX_METRICS_OPT_IN"].lower() == "true"
