import os
import platform
import subprocess
from typing import Optional, Dict, Any
import json
import hashlib

def get_system_info() -> Dict[str, Any]:
    """Collect basic system information."""
    return {
        "os": platform.system(),
        "os_version": platform.version(),
        "python_version": platform.python_version(),
        "python_implementation": platform.python_implementation(),
        "machine": platform.machine(),
    }

def run_command(command: str) -> Optional[str]:
    """Run a shell command and return its output."""
    try:
        result = subprocess.run(
            command,
            shell=True,
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        return result.stdout.strip()
    except subprocess.CalledProcessError:
        return None

def hash_sensitive_data(data: str) -> str:
    """Hash sensitive data to protect privacy."""
    return hashlib.sha256(data.encode()).hexdigest()

def get_git_config() -> Dict[str, Any]:
    """Collect non-sensitive git configuration."""
    git_config = {}

    # Get git version
    git_version = run_command("git --version")
    if git_version:
        git_config["version"] = git_version

    # Get user name and email (hashed)
    user_name = run_command("git config --global user.name")
    if user_name:
        git_config["user_name_hash"] = hash_sensitive_data(user_name)

    user_email = run_command("git config --global user.email")
    if user_email:
        git_config["user_email_hash"] = hash_sensitive_data(user_email)

    # Get common git settings
    git_config["settings"] = {}
    settings = [
        "core.editor",
        "core.autocrlf",
        "core.ignorecase",
        "core.excludesfile",
        "diff.tool",
        "merge.tool",
    ]

    for setting in settings:
        value = run_command(f"git config --global {setting}")
        if value:
            git_config["settings"][setting] = value

    return git_config

def get_ide_settings() -> Dict[str, Any]:
    """Collect IDE settings (non-sensitive)."""
    ide_settings = {}

    # VS Code
    vscode_path = os.path.expanduser("~/.vscode")
    if os.path.exists(vscode_path):
        ide_settings["vscode"] = {
            "installed": True,
            "extensions": [],
        }

        # Get installed extensions (non-sensitive)
        extensions_path = os.path.join(vscode_path, "extensions")
        if os.path.exists(extensions_path):
            try:
                extensions = os.listdir(extensions_path)
                ide_settings["vscode"]["extensions"] = [
                    ext.split("@")[0] for ext in extensions if "@" in ext
                ]
            except Exception:
                pass

    # JetBrains IDEs
    jetbrains_path = os.path.expanduser("~/.config/JetBrains")
    if os.path.exists(jetbrains_path):
        ide_settings["jetbrains"] = {
            "installed": True,
            "ides": [],
        }

        try:
            ides = os.listdir(jetbrains_path)
            ide_settings["jetbrains"]["ides"] = [
                ide for ide in ides if not ide.startswith(".")
            ]
        except Exception:
            pass

    return ide_settings

def get_ssh_info() -> Dict[str, Any]:
    """Collect SSH information (hashed for privacy)."""
    ssh_info = {}
    ssh_dir = os.path.expanduser("~/.ssh")

    if os.path.exists(ssh_dir):
        ssh_info["keys"] = []

        try:
            for item in os.listdir(ssh_dir):
                if item.endswith(".pub"):
                    key_path = os.path.join(ssh_dir, item)
                    try:
                        with open(key_path, "r") as f:
                            key_content = f.read().strip()
                            # Hash the public key fingerprint
                            ssh_info["keys"].append({
                                "name": item,
                                "fingerprint": hash_sensitive_data(key_content),
                            })
                    except Exception:
                        continue
        except Exception:
            pass

    return ssh_info

def get_cloud_providers() -> Dict[str, Any]:
    """Detect cloud provider configurations (non-sensitive)."""
    cloud_info = {}

    # AWS
    aws_dir = os.path.expanduser("~/.aws")
    if os.path.exists(aws_dir):
        cloud_info["aws"] = {
            "config_exists": True,
            "profiles": [],
        }

        try:
            config_path = os.path.join(aws_dir, "config")
            if os.path.exists(config_path):
                with open(config_path, "r") as f:
                    for line in f:
                        if line.strip().startswith("[profile"):
                            profile = line.strip()[9:-1]
                            cloud_info["aws"]["profiles"].append(profile)
        except Exception:
            pass

    # GCP
    gcp_dir = os.path.expanduser("~/.config/gcloud")
    if os.path.exists(gcp_dir):
        cloud_info["gcp"] = {
            "config_exists": True,
            "accounts": [],
        }

        try:
            accounts_path = os.path.join(gcp_dir, "credentials")
            if os.path.exists(accounts_path):
                with open(accounts_path, "r") as f:
                    data = json.load(f)
                    if "data" in data:
                        for account in data["data"]:
                            if "credential" in account and "account" in account["credential"]:
                                cloud_info["gcp"]["accounts"].append(
                                    hash_sensitive_data(account["credential"]["account"])
                                )
        except Exception:
            pass

    return cloud_info
