import os
import json
import boto3
import requests
from datetime import datetime

def lambda_handler(event, context):
    # Get environment variables
    audit_endpoint = os.environ['AUDIT_PLATFORM_ENDPOINT']
    api_key = os.environ['AUDIT_PLATFORM_API_KEY']
    state_bucket = os.environ['TERRAFORM_STATE_BUCKET']
    state_key = os.environ['TERRAFORM_STATE_KEY']

    # Initialize S3 client
    s3 = boto3.client('s3')

    try:
        # Get Terraform state file
        response = s3.get_object(Bucket=state_bucket, Key=state_key)
        state_content = response['Body'].read().decode('utf-8')
        state = json.loads(state_content)

        # Process resources
        compliance_report = {
            "timestamp": datetime.utcnow().isoformat(),
            "resources": [],
            "compliance_issues": []
        }

        # Basic compliance checks
        for resource in state.get('resources', []):
            resource_data = {
                "type": resource.get('type'),
                "name": resource.get('name'),
                "module": resource.get('module', 'root'),
                "instances": []
            }

            for instance in resource.get('instances', []):
                instance_data = {
                    "attributes": instance.get('attributes', {}),
                    "sensitive_attributes": []
                }

                # Check for sensitive attributes
                sensitive_attrs = ['password', 'secret', 'key', 'token', 'credential']
                for attr, value in instance.get('attributes', {}).items():
                    if any(sensitive in attr.lower() for sensitive in sensitive_attrs):
                        instance_data['sensitive_attributes'].append({
                            "name": attr,
                            "value": "REDACTED"  # Never log actual secrets
                        })

                # Add basic compliance checks
                if resource.get('type') == 'aws_db_instance':
                    if not instance.get('attributes', {}).get('storage_encrypted', False):
                        compliance_report['compliance_issues'].append({
                            "resource": f"{resource.get('type')}.{resource.get('name')}",
                            "issue": "Database storage not encrypted",
                            "severity": "high"
                        })

                if resource.get('type') == 'aws_s3_bucket':
                    if not instance.get('attributes', {}).get('server_side_encryption_configuration', {}):
                        compliance_report['compliance_issues'].append({
                            "resource": f"{resource.get('type')}.{resource.get('name')}",
                            "issue": "S3 bucket without server-side encryption",
                            "severity": "medium"
                        })

                resource_data['instances'].append(instance_data)

            compliance_report['resources'].append(resource_data)

        # Post to audit platform
        headers = {
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {api_key}'
        }

        response = requests.post(
            audit_endpoint,
            headers=headers,
            json=compliance_report,
            timeout=30
        )

        if response.status_code != 200:
            raise Exception(f"Audit platform returned status {response.status_code}: {response.text}")

        return {
            'statusCode': 200,
            'body': f"Compliance check completed. Found {len(compliance_report['compliance_issues'])} issues."
        }

    except Exception as e:
        return {
            'statusCode': 500,
            'body': f"Error during compliance check: {str(e)}"
        }
EOF
