                'unattached_policies': 0,
                'unused_entities': 0
            }
        }

    def get_all_iam_entities(self):
        """
        Enumerate all IAM users, roles, and policies in the account
        """
        print("Enumerating IAM entities...")

        # Get all users
        users = []
        paginator = self.iam.get_paginator('list_users')
        for page in paginator.paginate():
            users.extend(page['Users'])
        self.report['summary']['users'] = len(users)

        # Get all roles
        roles = []
        paginator = self.iam.get_paginator('list_roles')
        for page in paginator.paginate():
            roles.extend(page['Roles'])
        self.report['summary']['roles'] = len(roles)

        # Get all policies (AWS managed and customer managed)
        policies = []
        # AWS managed policies
        paginator = self.iam.get_paginator('list_policies')
        for page in paginator.paginate(Scope='AWS'):
            policies.extend(page['Policies'])
        # Customer managed policies
        paginator = self.iam.get_paginator('list_policies')
        for page in paginator.paginate(Scope='Local'):
            policies.extend(page['Policies'])
        self.report['summary']['policies'] = len(policies)

        return {
            'users': users,
            'roles': roles,
            'policies': policies
        }

    def get_entity_permissions(self, entity_type, entity_name):
        """
        Get all permissions for a given IAM entity (user or role)
        """
        permissions = []

        if entity_type == 'user':
            # Get inline policies
            try:
                paginator = self.iam.get_paginator('list_user_policies')
                for page in paginator.paginate(UserName=entity_name):
                    for policy_name in page['PolicyNames']:
                        policy_doc = self.iam.get_user_policy(
