    def __init__(self, profile_name=None, region='us-east-1'):
        self.session = boto3.Session(profile_name=profile_name, region_name=region)
        self.iam = self.session.client('iam')
        self.cloudtrail = self.session.client('cloudtrail')
        self.organizations = self.session.client('organizations') if profile_name else None

    def get_all_roles(self):
        """Retrieve all IAM roles in the account"""
        roles = []
        paginator = self.iam.get_paginator('list_roles')
        for page in paginator.paginate():
            roles.extend(page['Roles'])
        return roles

    def get_role_policies(self, role_name):
        """Get all policies attached to a role (inline and managed)"""
        policies = {
            'inline': [],
            'managed': []
        }

        # Get inline policies
        try:
            inline_policies = self.iam.list_role_policies(RoleName=role_name)
            for policy_name in inline_policies['PolicyNames']:
                policy_doc = self.iam.get_role_policy(
                    RoleName=role_name,
                    PolicyName=policy_name
                )
                policies['inline'].append({
                    'name': policy_name,
                    'document': policy_doc['PolicyDocument']
                })
        except self.iam.exceptions.NoSuchEntityException:
            pass

        # Get managed policies
        try:
            managed_policies = self.iam.list_attached_role_policies(RoleName=role_name)
            for policy in managed_policies['AttachedPolicies']:
                policy_arn = policy['PolicyArn']
                policy_version = self.iam.get_policy(PolicyArn=policy_arn)['Policy']['DefaultVersionId']
                policy_doc = self.iam.get_policy_version(
                    PolicyArn=policy_arn,
                    VersionId=policy_version
                )['PolicyVersion']['Document']
                policies['managed'].append({
                    'name': policy['PolicyName'],
                    'arn': policy_arn,
                    'document': policy_doc
                })
        except self.iam.exceptions.NoSuchEntityException:
            pass

        return policies

